def solve(grid):
    rows = len(grid)
    cols = len(grid[0])

    cross_row = cross_col = None
    for r in range(rows):
        if all(grid[r][c] == 5 for c in range(cols)):
            cross_row = r
    for c in range(cols):
        if all(grid[r][c] == 5 for r in range(rows)):
            cross_col = c

    row_indices = [r for r in range(rows) if r != cross_row]
    col_indices = [c for c in range(cols) if c != cross_col]

    g = [[grid[row_indices[i]][col_indices[j]] for j in range(4)] for i in range(4)]

    values = set()
    for i in range(4):
        for j in range(4):
            if g[i][j] != 0:
                values.add(g[i][j])
    values = list(values)

    zeros = [(i, j) for i in range(4) for j in range(4) if g[i][j] == 0]

    def can_place(i, j, v):
        for jj in range(4):
            if jj != j and g[i][jj] == v:
                return False
        for ii in range(4):
            if ii != i and g[ii][j] == v:
                return False
        bi, bj = (i // 2) * 2, (j // 2) * 2
        for di in range(2):
            for dj in range(2):
                ii, jj = bi + di, bj + dj
                if (ii, jj) != (i, j) and g[ii][jj] == v:
                    return False
        return True

    def backtrack(idx):
        if idx == len(zeros):
            return True
        i, j = zeros[idx]
        for v in values:
            if can_place(i, j, v):
                g[i][j] = v
                if backtrack(idx + 1):
                    return True
                g[i][j] = 0
        return False

    backtrack(0)

    output = [row[:] for row in grid]
    for i in range(4):
        for j in range(4):
            output[row_indices[i]][col_indices[j]] = g[i][j]

    return output
